void main() {
  group('/dap TUI menu', () {
    test('slash menu shows the /dap hint', () async {
      final tempHome = _tempHome();
      final harness = await FaCliHarness.spawn(
        extraEnv: {
          'HOME': tempHome.path,
          'DAP_LOCAL_HUB_URL': await deadLocalHubUrl(),
        },
